files.quantity.mjs:
export function quantity(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) throw new Error('Invalid quantity');
  return n || 1;
}

files.quantity.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { quantity } from './quantity.mjs';
test('quantity', () => {
  assert.equal(quantity('2'), 2);
  for (const value of ['bad', '-1', '1.5']) assert.throws(() => quantity(value), /Invalid quantity/);
});

